<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { listTemplateVersions, listTemplates } from '../api/templates'
import { createTaskSchedule, listScheduleTargets, listTaskScheduleRuns, listTaskSchedules, pauseTaskSchedule, resumeTaskSchedule, runTaskScheduleNow, updateTaskSchedule, type ScheduleRun, type ScheduleTarget } from '../api/taskSchedules'
import type { TaskSchedule, Template, TemplateVersion } from '../types'

const schedules = ref<TaskSchedule[]>([]); const templates = ref<Template[]>([]); const versions = ref<TemplateVersion[]>([]); const targets = ref<ScheduleTarget[]>([]); const runs = ref<ScheduleRun[]>([])
const editing = ref<TaskSchedule | null>(null); const showEditor = ref(false); const runFor = ref<TaskSchedule | null>(null); const error = ref(''); const message = ref('')
const form = ref({ name: '', templateId: '', templateVersionId: '', frequency: 'MONTHLY', weekDay: 1, dayOfMonth: 1, monthOfYear: 1, publishTime: '09:00', deadlineDays: 3, allowLate: false, startAt: '', endAt: '', description: '', assigneeIds: [] as Array<number | string>, departmentIds: [] as Array<number | string> })
const reporters = computed(() => targets.value.filter(item => item.type === 'REPORTER')); const departments = computed(() => targets.value.filter(item => item.type === 'DEPARTMENT'))
function msg(value: unknown) { return value instanceof Error ? value.message : '操作失败' }
function date(value?: string) { return value ? value.replace('T', ' ') : '-' }
async function loadVersions(templateId: string, preferred?: number | string) { versions.value = templateId ? await listTemplateVersions(templateId) : []; form.value.templateVersionId = preferred == null ? String(versions.value[0]?.id || '') : String(preferred) }
async function load() { try { [schedules.value, templates.value, targets.value] = await Promise.all([listTaskSchedules(), listTemplates(), listScheduleTargets()]) } catch (caught) { error.value = msg(caught) } }
function openCreate() { editing.value = null; const templateId = String(templates.value[0]?.id || ''); form.value = { name: '', templateId, templateVersionId: '', frequency: 'MONTHLY', weekDay: 1, dayOfMonth: 1, monthOfYear: 1, publishTime: '09:00', deadlineDays: 3, allowLate: false, startAt: '', endAt: '', description: '', assigneeIds: [], departmentIds: [] }; showEditor.value = true; void loadVersions(templateId) }
function openEdit(item: TaskSchedule) { editing.value = item; form.value = { name: item.name, templateId: String(item.templateId), templateVersionId: String(item.templateVersionId), frequency: item.frequency, weekDay: item.weekDay || 1, dayOfMonth: item.dayOfMonth ?? 1, monthOfYear: item.monthOfYear || 1, publishTime: item.publishTime.slice(0, 5), deadlineDays: item.deadlineDays, allowLate: item.allowLate, startAt: item.startAt?.slice(0, 16) || '', endAt: item.endAt?.slice(0, 16) || '', description: item.description || '', assigneeIds: [...(item.assigneeIds || [])], departmentIds: [...(item.departmentIds || [])] }; showEditor.value = true; void loadVersions(String(item.templateId), item.templateVersionId) }
function cancel() { showEditor.value = false; editing.value = null }
async function save() { if (!form.value.name.trim() || !form.value.templateId || !form.value.templateVersionId || (!form.value.assigneeIds.length && !form.value.departmentIds.length)) { error.value = '名称、模板、版本和至少一名填报人员或目标部门不能为空'; return }; const payload = { ...form.value, templateId: Number(form.value.templateId), templateVersionId: Number(form.value.templateVersionId), startAt: form.value.startAt || undefined, endAt: form.value.endAt || undefined, assigneeIds: form.value.assigneeIds.map(Number), departmentIds: form.value.departmentIds.map(Number) }; try { editing.value ? await updateTaskSchedule(editing.value.id, payload) : await createTaskSchedule(payload); message.value = editing.value ? '定时规则已更新，仅影响后续周期' : '定时规则已创建'; cancel(); await load() } catch (caught) { error.value = msg(caught) } }
async function toggle(item: TaskSchedule) { try { item.status === 'ACTIVE' ? await pauseTaskSchedule(item.id) : await resumeTaskSchedule(item.id); await load() } catch (caught) { error.value = msg(caught) } }
async function runNow(item: TaskSchedule) { try { const run = await runTaskScheduleNow(item.id); message.value = run.status === 'SUCCESS' ? '已立即发布任务' : `执行结果：${run.status}${run.errorMessage ? `，${run.errorMessage}` : ''}`; await load() } catch (caught) { error.value = msg(caught) } }
async function openRuns(item: TaskSchedule) { runFor.value = item; try { runs.value = await listTaskScheduleRuns(item.id) } catch (caught) { error.value = msg(caught) } }
onMounted(load)
</script>

<template><section><div class="page-heading"><div><h1>定时发布</h1><p>按固定模板版本和周期自动发布填报任务；暂停或修改规则只影响后续周期。</p></div><button class="primary" @click="openCreate">新建规则</button></div><div v-if="message" class="notice success">{{ message }}</div><div v-if="error" class="notice error">{{ error }}</div><form v-if="showEditor" class="editor" @submit.prevent="save"><h2>{{ editing ? '编辑定时规则' : '新建定时规则' }}</h2><div class="form-grid"><label>规则名称<input v-model.trim="form.name" maxlength="128" /></label><label>模板<select v-model="form.templateId" @change="loadVersions(form.templateId)"><option value="">请选择模板</option><option v-for="item in templates" :key="item.id" :value="String(item.id)">{{ item.name }}</option></select></label><label>固定模板版本<select v-model="form.templateVersionId"><option v-for="item in versions" :key="item.id" :value="String(item.id)">V{{ item.versionNo }}</option></select></label><label>频率<select v-model="form.frequency"><option value="WEEKLY">每周</option><option value="MONTHLY">每月</option><option value="YEARLY">每年</option></select></label><label v-if="form.frequency==='WEEKLY'">星期<select v-model.number="form.weekDay"><option v-for="day in 7" :key="day" :value="day">星期{{ ['一','二','三','四','五','六','日'][day-1] }}</option></select></label><label v-else>日期<select v-model.number="form.dayOfMonth"><option :value="0">最后一天</option><option v-for="day in 31" :key="day" :value="day">{{ day }} 日</option></select></label><label v-if="form.frequency==='YEARLY'">月份<select v-model.number="form.monthOfYear"><option v-for="month in 12" :key="month" :value="month">{{ month }} 月</option></select></label><label>发布时间<input v-model="form.publishTime" type="time" /></label><label>发布后截止天数<input v-model.number="form.deadlineDays" min="1" max="365" type="number" /></label><label>开始生效<input v-model="form.startAt" type="datetime-local" /></label><label>结束生效<input v-model="form.endAt" type="datetime-local" /></label><label class="checkbox-label"><input v-model="form.allowLate" type="checkbox" />允许逾期填报</label><label>规则说明<input v-model.trim="form.description" maxlength="500" /></label></div><fieldset class="choice-set"><legend>填报人员或目标部门</legend><div class="compact-choices"><label v-for="item in reporters" :key="item.id"><input v-model="form.assigneeIds" type="checkbox" :value="item.id" />{{ item.name }}</label></div></fieldset><fieldset class="choice-set"><legend>目标部门（自动展开子部门填报人员）</legend><div class="compact-choices"><label v-for="item in departments" :key="item.id"><input v-model="form.departmentIds" type="checkbox" :value="item.id" />{{ item.name }}</label></div></fieldset><div class="actions"><button class="primary">保存</button><button type="button" class="secondary" @click="cancel">取消</button></div></form><div class="table-wrap"><table><thead><tr><th>规则</th><th>模板版本</th><th>周期</th><th>下次发布</th><th>截止</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="!schedules.length"><td colspan="7" class="muted">暂无定时发布规则。</td></tr><tr v-for="item in schedules" :key="item.id"><td>{{ item.name }}</td><td>{{ item.templateName }} V{{ item.templateVersionNo }}</td><td>{{ item.frequency }}</td><td>{{ date(item.nextRunAt) }}</td><td>发布后 {{ item.deadlineDays }} 天</td><td>{{ item.status === 'ACTIVE' ? '启用' : '暂停' }}</td><td><button class="text-button" @click="openEdit(item)">修改</button><button class="text-button" @click="toggle(item)">{{ item.status === 'ACTIVE' ? '暂停' : '恢复' }}</button><button class="text-button" @click="runNow(item)">立即执行</button><button class="text-button" @click="openRuns(item)">记录</button></td></tr></tbody></table></div><div v-if="runFor" class="modal-backdrop" @click.self="runFor = null"><section class="detail-modal"><header class="detail-modal-header"><div><h2>{{ runFor.name }}执行记录</h2></div><button class="text-button" @click="runFor = null">关闭</button></header><div class="detail-table-scroll"><table><thead><tr><th>周期</th><th>任务</th><th>结果</th><th>原因</th><th>时间</th></tr></thead><tbody><tr v-if="!runs.length"><td colspan="5" class="muted">暂无执行记录。</td></tr><tr v-for="run in runs" :key="run.id"><td>{{ run.periodKey }}</td><td>{{ run.taskId || '-' }}</td><td>{{ run.status }}</td><td>{{ run.errorMessage || '-' }}</td><td>{{ date(run.executedAt) }}</td></tr></tbody></table></div></section></div></section></template>
